public partial class OfficerDetailDialog:AcceptDialog
{
    public event Action<Command>? CommandIssued;
    private ContentSet _content=null!;private EmpireView _view=null!;private VBoxContainer _body=null!;
    private readonly ItemList _list=new(){Name="OfficerList",SelectMode=ItemList.SelectModeEnum.Multi,CustomMinimumSize=new(0,120)};
    private readonly List<OfficerId> _rows=new();private readonly Label _detail=DevelopmentUi.Text(""),_error=DevelopmentUi.Text("","WarningLabel");private readonly VBoxContainer _career=new();
    private bool _showTurnDetails;
    private readonly OptionButton _doctrine=new(){Name="OfficerDoctrine"},_future=new(){Name="OfficerFutureDoctrine"},_posting=new(){Name="OfficerPosting"},_fleet=new(){Name="OfficerFleet"},_candidate=new(){Name="OfficerCandidate"},_specialty=new(){Name="OfficerBodySpecialty"};
    private readonly Label _confirmationText=DevelopmentUi.Text("");private readonly ConfirmationDialog _confirm=new(){Name="OfficerConfirmation",Title="Review appointment",OkButtonText="Apply appointment"};private OfficerCommand? _pending;
    public override void _Ready()
    {
        Name="OfficerDetailDialog";Title="Admirals and service records";OkButtonText="Close";_body=DevelopmentUi.DialogBody(this);_body.AddChild(DevelopmentUi.Text("Optional named command appointments. Specialties are fixed; experience unlocks passive abilities at 10 and 30 XP. There are no ability points or respec actions."));_body.AddChild(_list);_body.AddChild(_detail);
        _body.AddChild(_doctrine);_doctrine.AddItem("Recover command / re-establish Wenth link");_doctrine.AddItem("Last watch (manual choice)");DevelopmentUi.Button(_body,"Apply doctrine to selected officers",()=>Review(new OfficerAction.ApplyDoctrineToSelection(Selected(),(OfficerDoctrine)_doctrine.Selected),"Only selected active records change. Last watch gives mortal officers no recovery roll; Wenth use the longer link delay. Applies to subsequent losses; an existing recovery keeps its captured outcome and deadline."),"OfficerApplyDoctrine");
        _body.AddChild(_future);_future.AddItem("Future commissions: cultural default (recovery)");_future.AddItem("Future commissions: Recover command");_future.AddItem("Future commissions: Last watch");DevelopmentUi.Button(_body,"Set future commission doctrine",()=>Review(new OfficerAction.SetFutureDoctrine(_future.Selected==0?null:_future.Selected==1?OfficerDoctrine.RecoverCommand:OfficerDoctrine.LastWatch),"Existing officers are unchanged. This explicit choice applies to future commissions."),"OfficerSetFuture");
        _body.AddChild(new HSeparator());_body.AddChild(DevelopmentUi.Text("Physical posting and command", "HeaderLabel"));_body.AddChild(_posting);_body.AddChild(_fleet);var actions=new GridContainer{Columns=2};_body.AddChild(actions);
        DevelopmentUi.Button(actions,"Assign to selected fleet",()=>One(o=>{if(Fleet() is {} f)Review(new OfficerAction.AssignFlagship(o.Id,f),"Board the designated flagship only at the officer's current owned colony system. A fleet works without an admiral.");}),"OfficerAssign");
        DevelopmentUi.Button(actions,"Transfer between flagships",()=>One(o=>{if(o.Flagship is {} from&&Fleet() is {} id)Review(new OfficerAction.Transfer(o.Id,from,_view.Fleets!.Fleets.Single(f=>f.Id==id).Flagship),"Both own flagships must be stationary and co-located; destination command must be free.");else _error.Text="Select an officer currently commanding a flagship.";}),"OfficerTransfer");
        DevelopmentUi.Button(actions,"Remove to selected owned colony",()=>One(o=>{if(Posting() is {} col)Review(new OfficerAction.Remove(o.Id,col),"Removal requires physical co-location. Leaving request coordination permanently forfeits that request's officer XP.");}),"OfficerRemove");
        DevelopmentUi.Button(actions,"Change posting in this system",()=>One(o=>{if(Posting() is {} col)Review(new OfficerAction.Post(o.Id,col),"Posting changes require the same owned colony system; this does not transport an officer.");}),"OfficerPost");
        DevelopmentUi.Button(actions,"Dismiss appointment permanently",()=>One(o=>Review(new OfficerAction.Dismiss(o.Id),"This ends the appointment permanently and retains its final career record. It does not refund or reset the lifetime commission count.")),"OfficerDismiss");
        _body.AddChild(new HSeparator());_body.AddChild(DevelopmentUi.Text("Commission an appointment", "HeaderLabel"));_body.AddChild(_candidate);_body.AddChild(_specialty);foreach(var specialty in Enum.GetValues<OfficerSpecialty>())_specialty.AddItem(specialty.ToString());
        DevelopmentUi.Button(_body,"Commission at selected posting",()=>{if(Posting() is not {} posting){_error.Text="An owned colony is required.";return;}bool body=_content.Species[_view.SpeciesId!].CommandEmbodiment==CommandEmbodiment.ColonyBody;if(!body&&_candidate.ItemCount==0){_error.Text="No candidate is available.";return;}Review(new OfficerAction.Commission(body?null:_candidate.GetSelectedMetadata().AsString(),posting,body?posting:null,body?(OfficerSpecialty)_specialty.Selected:null),$"Available after {_content.FleetCommand!.CommissionTurns} turns. Counts against {_content.FleetCommand.ActiveOfficerLimit} active / {_content.FleetCommand.LifetimeCommissionLimit} lifetime appointments. Wenth appoint a whole source body; no population is spent.");},"OfficerCommission");
        _body.AddChild(DevelopmentUi.Text("Service record", "HeaderLabel"));DevelopmentUi.Button(_body,"Show / hide completed-turn details",()=>{_showTurnDetails=!_showTurnDetails;Details();},"OfficerToggleTurnDetails");_body.AddChild(_career);_error.Name="OfficerError";_detail.Name="OfficerDetails";_body.AddChild(_error);AddChild(_confirm);DevelopmentUi.DialogBody(_confirm).AddChild(_confirmationText);_confirm.Confirmed+=()=>{if(_pending is {} command)CommandIssued?.Invoke(command);_pending=null;};_list.MultiSelected+=(_,_)=>Details();
    }
    public void ShowOfficers(ContentSet content,EmpireView view)
    {
        _content=content;_view=view;var old=Selected().ToHashSet();_list.Clear();_rows.Clear();foreach(var o in view.Fleets!.Officers.OrderBy(o=>o.Id)){_rows.Add(o.Id);_list.AddItem($"{o.Name} — {o.Specialty}, {o.Xp}/{content.FleetCommand!.XpCap} XP, {o.Status}");if(old.Contains(o.Id))_list.Select(_list.ItemCount-1,false);}if(_list.ItemCount>0&&_list.GetSelectedItems().Length==0)_list.Select(0);
        Fill(_posting,view.Colonies.OrderBy(c=>c.Id).Select(c=>(c.Id.Value,$"Posting: {Colony(c.Id)}")));Fill(_fleet,view.Fleets.Fleets.OrderBy(f=>f.Id).Select(f=>(f.Id.Value,$"Fleet: {f.Name} / flagship {f.Flagship.Value}")));
        _candidate.Clear();foreach(var candidate in view.Fleets.Candidates){_candidate.AddItem($"{candidate.Name} — {candidate.Specialty}");_candidate.SetItemMetadata(_candidate.ItemCount-1,candidate.ProfileId);}bool body=content.Species[view.SpeciesId!].CommandEmbodiment==CommandEmbodiment.ColonyBody;_candidate.Visible=!body;_specialty.Visible=body;_doctrine.SetItemText(0,body?"Re-establish command link":"Recover command");_future.Select(view.Fleets.FutureDoctrine is null?0:view.Fleets.FutureDoctrine==OfficerDoctrine.RecoverCommand?1:2);Details();PopupCenteredClamped(new(740,560));
    }
    private ImmutableArray<OfficerId> Selected()=>_list.GetSelectedItems().Select(i=>_rows[i]).ToImmutableArray();
    private ColonyId? Posting()=>_posting.ItemCount==0?null:new(_posting.GetSelectedMetadata().AsInt32());private FleetId? Fleet()=>_fleet.ItemCount==0?null:new(_fleet.GetSelectedMetadata().AsInt32());
    private static void Fill(OptionButton picker,System.Collections.Generic.IEnumerable<(int Id,string Text)> rows){int old=picker.ItemCount>0?picker.GetSelectedMetadata().AsInt32():0;picker.Clear();foreach(var row in rows){picker.AddItem(row.Text);picker.SetItemMetadata(picker.ItemCount-1,row.Id);if(row.Id==old)picker.Select(picker.ItemCount-1);}picker.FitToLongestItem=false;picker.ClipText=true;}
    private string Colony(ColonyId id)=>_view.Research.ColonyNames.TryGetValue(id.ToString(),out var name)?name:$"former colony {id.Value}";
    private void One(Action<OfficerView> action){var ids=Selected();if(ids.Length==1)action(_view.Fleets!.Officers.Single(o=>o.Id==ids[0]));else _error.Text="Select exactly one officer.";}
    private void Details()
    {
        DevelopmentUi.Clear(_career);var ids=Selected();if(ids.Length!=1){_detail.Text=$"{ids.Length} selected. Bulk doctrine applies atomically to this selection.";return;}var o=_view.Fleets!.Officers.Single(o=>o.Id==ids[0]);var d=_content.FleetCommand!;_doctrine.Select((int)o.Doctrine);string embodiment=o.Embodiment==CommandEmbodiment.ColonyBody?$"Whole source body: {Colony(o.SourceBody!.Value)}. This is a command appointment, not a recruitable limb.":$"{o.Pronouns}. {o.Personality}";
        int tier=o.Rank;string bonus=o.Specialty switch{OfficerSpecialty.Navigator=>$"Unlocked fleet travel bonus {(tier==0?0:d.NavigatorBonuses[tier-1])}%; currently active {(o.Status==OfficerStatus.Commanding&&tier>0?d.NavigatorBonuses[tier-1]:0)}%. Applies only to the commanded fleet; hull study/escape odds unchanged.",OfficerSpecialty.Surveyor=>$"Unlocked first-survey research {Format.Points(tier==0?0:d.SurveyResearchBonuses[tier-1])}; only a commanding flagship earns this event, using pre-event rank.",_=>$"Unlocked request-ship discount {(tier==0?0:d.OrganizerDiscounts[tier-1])}%; only active, unpaused bound work while physically posted as its coordinator receives it."};
        _detail.Text=$"{o.Name} — {o.Specialty}, rank {tier}, XP {o.Xp}/{d.XpCap}. {(o.Xp<10?"Next passive unlock: 10 XP.":o.Xp<30?"Next passive unlock: 30 XP.":"All passive tiers unlocked.")} {embodiment}\n{bonus}\nStatus: {o.Status}. {(o.PostedColony is {} col?$"Posted: {Colony(col)}.":"")}{(o.Flagship is {} v?$" Flagship {v.Value}.":"")}{(o.AvailableAtTurn is {} due?$" Available turn {due}; countdown is not sped up by waiting in this window.":"")}{(o.RecoveryColony is {} recovery?$" Recovery destination: {Colony(recovery)}.":"")}\nCulture: {d.Cultures.Single(c=>c.Id==o.CultureId).Name}. Current doctrine: {(o.Doctrine==OfficerDoctrine.LastWatch?"Last watch":o.Embodiment==CommandEmbodiment.ColonyBody?"Re-establish command link":"Recover command")}. Recovery equipment is researched separately; doctrine is editable from the start. {o.FinalSummary}";
        _career.AddChild(DevelopmentUi.Text($"Totals: {o.Career.FirstSurveys} first surveys; {o.Career.CompletedRequests} completed requests / {o.Career.NewHulls} original new hulls; {o.Career.Studies} studies; {o.Career.ShipsLost} ships / {o.Career.FlagshipsLost} flagships lost; {o.Career.Recoveries} recoveries."));foreach(var h in o.Highlights.OrderByDescending(h=>h.Event))_career.AddChild(DevelopmentUi.Text($"Turn {h.Turn}: {h.Kind.Replace('_',' ')}. {h.Reason}"));
        _career.AddChild(DevelopmentUi.Text($"Retains up to {d.HighlightLimit} career highlights and {d.DetailTurnLimit} completed-turn detail records; final careers remain permanent."));
        if(_showTurnDetails)foreach(var turn in o.Details.OrderByDescending(t=>t.Turn)){_career.AddChild(DevelopmentUi.Text($"Completed turn {turn.Turn}","HeaderLabel"));foreach(var entry in turn.Entries)_career.AddChild(DevelopmentUi.Text($"{entry.Kind.Replace('_',' ')}. {entry.Reason}"));}
    }
    public void ShowError(string text)=>_error.Text=text;
    private void Review(OfficerAction action,string reason){_pending=new(_view.Viewer,_view.Turn,action);_error.Text="";_confirmationText.Text=reason;_confirm.PopupCenteredClamped(new(640,400));}
